def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Infer background as most common. Interior non-background points are
    # markers: recolor each to 4 and extend its color toward nearest border.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    border={grid[0][c] for c in range(w)}|{grid[h-1][c] for c in range(w)}|{grid[r][0] for r in range(h)}|{grid[r][w-1] for r in range(h)}
    marker_colors={grid[r][c] for r in range(1,h-1) for c in range(1,w-1) if grid[r][c]!=bg}
    mc=next((v for v in marker_colors if v not in border), None)
    if mc is None: return out
    # Border bars define which orientation to project: horizontal edge bars
    # cause vertical columns; vertical edge bars cause horizontal rows.
    horiz=sum(grid[0][c]!=bg for c in range(w))+sum(grid[h-1][c]!=bg for c in range(w))
    vert=sum(grid[r][0]!=bg for r in range(h))+sum(grid[r][w-1]!=bg for r in range(h))
    vertical=horiz>=vert
    for r in range(1,h-1):
      for c in range(1,w-1):
        if grid[r][c]==mc:
          out[r][c]=4
          if vertical:
            # Fill toward top/bottom boundaries; stop at non-background.
            for dr in (-1,1):
              rr=r+dr
              while 0<rr<h-1 and grid[rr][c]==bg:
                out[rr][c]=mc; rr+=dr
          else:
            for dc in (-1,1):
              cc=c+dc
              while 0<cc<w-1 and grid[r][cc]==bg:
                out[r][cc]=mc; cc+=dc
    # 2nd rule: region behind a same-color boundary bar is filled to marker
    # row/column, as seen in demos where colored border markers initiate fill.
    if vertical:
      for c in range(w):
        if grid[0][c]!=bg:
          # project the bar cell down through the background interior
          for r in range(1,h-1):
            if grid[r][c]==bg: out[r][c]=mc
    else:
      for r in range(h):
        if grid[r][0]!=bg:
          for c in range(1,w-1):
            if grid[r][c]==bg: out[r][c]=mc
    return out
